// This Verus program checks whether every element of `arr1` is strictly
// greater than the corresponding element of `arr2`.  By convention,
// for empty arrays the result is `true`.
//
// We assume both vectors have the same length.
//
// To verify with Verus, save this in a `.rs` file and run `verus <file>.rs`.

verus! {
    use std::vec::Vec;

    pub fn is_smaller(arr1: &Vec<i32>, arr2: &Vec<i32>) -> (result: bool)
        // the two arrays must have equal length
        requires arr1.len() == arr2.len()
        // the result is true exactly when for all valid indices i,
        // arr1[i] > arr2[i]
        ensures
            result
            == forall |i: usize| i < arr1.len() ==> arr1[i] > arr2[i]
    {
        let mut i: usize = 0;
        // We iterate from 0 up to arr1.len(), checking each pair.
        while i < arr1.len() {
            // loop invariants:
            // 1) `i` is never more than the length
            invariant i <= arr1.len();
            // 2) for all j < i, we've already checked arr1[j] > arr2[j]
            invariant forall |j: usize| j < i ==> arr1[j] > arr2[j];
            // decreases clause to show termination
            decreases arr1.len() - i;

            // If any pair fails the check, return false immediately.
            if !(arr1[i] > arr2[i]) {
                return false;
            }
            i += 1;
        }

        // If we never found a counterexample, return true.
        true
    }
}